const results = [];

for (const item of $input.all()) {

  if (!item.json.output || item.json.output.toString().trim() === "") {
    continue;
  }

  let raw = item.json.output.toString();

  // Remove markdown code fences
  raw = raw.replace(/```json|```/g, "").trim();

  let data;
  try {
    data = JSON.parse(raw);
  } catch (e) {
    continue;
  }

  const reply = (data.reply || "")
    .toString()
    .replace(/\r?\n/g, "\\n")
    .trim();

  if (reply === "") {
    continue;
  }

  results.push({
    json: {
      reply: reply
    }
  });
}

return results;

const staticData = $getWorkflowStaticData('global');

const msg =
  $json.body?.entry?.[0]?.messaging?.[0]?.message;

const mid = msg?.mid;

if (!mid) {
  return [];
}

if (!staticData.processed) {
  staticData.processed = {};
}

if (staticData.processed[mid]) {
  return [];
}

staticData.processed[mid] = Date.now();

for (const k in staticData.processed) {
  if (Date.now() - staticData.processed[k] > 120000) {
    delete staticData.processed[k];
  }
}

return [$json];

const rows = $input.all();

// Sort rows by row number to maintain order
rows.sort((a, b) => (a.json.row_number || 0) - (b.json.row_number || 0));

// Build history in AI → User → AI → User format
const history = [];

for (const r of rows) {
  const aiReply = r.json["AI reply"] || "";
  const userMsg = r.json["User message"] || "";

  if (aiReply.trim() !== "") {
    history.push({ role: "AI", text: aiReply.trim() });
  }
  if (userMsg.trim() !== "") {
    history.push({ role: "User", text: userMsg.trim() });
  }
}

// Add NEW incoming message from Instagram webhook
const newUserMsg =
  $node["Instagram DM"].json.body.entry[0].messaging[0]?.message?.text
  || "[No text]";

history.push({ role: "User", text: newUserMsg.trim() });

// Build FULL conversation log as readable string
const conversationLog = history
  .map(h => `${h.role}: ${h.text}`)
  .join(" | ");

// Take last 5 exchanges = 10 messages max
const last5Exchanges = history.slice(-10);

// Convert last 5 exchanges into CHAT TEXT (not array)
const last5Formatted = last5Exchanges
  .map(h => `${h.role}: ${h.text}`)
  .join("\n");

return [{
  json: {
    sender_id: $node["Extracts ID"].json["body.entry[0].messaging[0].sender.id"],
    conversation_log: conversationLog,
    last_5_messages: last5Formatted
  }
}];
